source.quote:
  status="$(cat "$REPO_DIR/status" 2>/dev/null || true)"
fi
case "$status" in
  needs_input|blocked|waiting|orphaned) ;;
  *) _die "Worker status '$status' is not waiting or resumable; response was not published" ;;

done)
  [[ -s "$WORKTREE/.sergeant-result" ]] || _die "Response acknowledgement requires done with a non-empty result"
  ;;
failed:\ *[![:space:]]) ;;
failed:*) _die "Response acknowledgement requires failed with a nonblank reason" ;;

source "$SCRIPT_DIR/_sgt-harness.sh"

[[ -d "$WORKTREE" ]] || {
  echo "ERROR: worktree unavailable: $WORKTREE" >&2
  exit 2
}
[[ -t 0 && -t 1 ]] || {
  echo "ERROR: interactive worker requires a terminal" >&2

case "$MESSAGE" in
  done*|failed*) _event="completion"; _heading="Agent Completion" ;;
  needs_input*|blocked*) _event="escalation"; _heading="Agent Escalation" ;;
  *) _event="update"; _heading="Agent Update" ;;
esac
